<template><a-card><a-space direction="vertical" fill><a-space><a-select v-model="account" placeholder="选择账号" style="width:260px" @change="load"><a-option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name||a.username||a.id}}</a-option></a-select></a-space><a-table :data="rows"><template #columns><a-table-column title="Telegram Chat ID" data-index="telegram_chat_id"/><a-table-column title="名称" data-index="title"/><a-table-column title="类型" data-index="type"/><a-table-column title="可选"><template #cell="{record}">{{record.selectable?'是':'否'}}</template></a-table-column><a-table-column title="操作"><template #cell="{record}"><a-space><a-button v-if="record.selectable" type="primary" size="small" @click="enable(record)">启用 Source</a-button><a-popconfirm content="删除 Dialog 管理记录？需先禁用 Source。" @ok="remove(record.telegram_chat_id)"><a-button type="text" status="danger">删除</a-button></a-popconfirm></a-space></template></a-table-column></template></a-table></a-space></a-card></template><script setup lang="ts">import {onMounted,ref} from "vue";import {telegram} from "../api";import {Message} from "@arco-design/web-vue";const accounts=ref<any[]>([]),account=ref<number>(),rows=ref<any[]>([]);async function load(){if(account.value)rows.value=(await telegram.dialogs(account.value)).data}async function enable(r:any){try{await telegram.createSource({account_id:account.value,telegram_chat_id:r.telegram_chat_id,name:r.title||r.name||String(r.telegram_chat_id)});Message.success("Source 已启用");load()}catch(e:any){Message.error(e.response?.data?.detail||"启用 Source 失败")}}async function remove(id:number){try{await telegram.deleteDialog(account.value!,id);Message.success("已删除");load()}catch(e:any){Message.error(e.response?.data?.detail||"删除失败")}}onMounted(async()=>{accounts.value=await telegram.accounts().then(r=>r.data);if(accounts.value[0]){account.value=accounts.value[0].id;load()}})</script>